function taskOutputStage(attempt,logs){const labels={odm_load_dataset:'Loading photos',dataset:'Loading photos',split:'Splitting dataset',merge:'Merging submodels',opensfm:'Camera reconstruction',openmvs:'Dense reconstruction',odm_filterpoints:'Filtering point cloud',odm_meshing:'Building mesh',odm_texturing:'Texturing model',odm_georeferencing:'Georeferencing',odm_dem:'Elevation models',odm_orthophoto:'Orthophoto',odm_report:'Quality report',odm_postprocess:'Finalizing outputs'};if(!['running','queued_upstream'].includes(attempt.status))return String(attempt.status||'unknown').replaceAll('_',' ');for(const log of [...logs].reverse()){const match=String(log.message||'').replace(/\x1b\[[0-9;]*m/g,'').match(/\b(?:running|starting)\s+(?:(?:stage|step)\s*[:=]?\s*)?[\x22\x27]?(odm_[a-z]+|opensfm|openmvs|dataset|split|merge)\b/i);if(match&&labels[match[1].toLowerCase()])return labels[match[1].toLowerCase()]}return attempt.status==='queued_upstream'?'Waiting for processing node':'Processing — stage not reported in recent output'}
