let activeNewTask=null;
function processModal(projectId){
  const project=state.projects.find(item=>item.id===projectId);if(!project||project.status!=='active'||!can('viewer.processing.write'))return;
  if(activeNewTask?.active){activeNewTask.reopen();return;}
  // Separate from the shared workspace modal: navigating or opening another
  // settings dialog must not destroy a browser-owned photo upload.
  const taskDialog=document.createElement('dialog');taskDialog.className='workspace-modal';taskDialog.setAttribute('aria-label','New processing task');
  const taskContent=document.createElement('div');taskContent.innerHTML='<div class="modal-heading"><div><p class="eyebrow">Viewer workspace</p><h2>New task</h2></div><button type="button" class="icon-button modal-close" aria-label="Close task dialog">×</button></div>';
  taskDialog.append(taskContent);document.body.append(taskDialog);taskContent.querySelector('.modal-close').onclick=()=>taskDialog.close();
  activeNewTask=mountNewTask({container:taskContent,dialog:taskDialog,project,providers:state.providers,presets:state.presets,datasets:state.datasets,api,fetcher:workspaceFetch,token:()=>state.token,canUpload:can('viewer.datasets.write'),canImport:can('viewer.datasets.import'),canManagePresets:can('viewer.providers.write'),allowBackground:true,onDispose:()=>{taskDialog.remove();activeNewTask=null;},onComplete:async()=>{toast('Processing task submitted');await load();}});taskDialog.showModal();
}
